// Foto kampanye RRI untuk kartu "Campaigns that delivered" di landing page
// (PR landing-kampanye-foto, 2026-11-18).
//
// Sumber: 7 file foto yang DIUNGGAH PENGGUNA (bukan unduhan web), di-embed
// sebagai data URI base64 karena push snapshot GitHub hanya menerima file
// teks (pola yang sama seperti logoMitra.ts / logoLayanan.ts).
//
// Pemrosesan (PIL, dari file asli): center-crop ke aspek 7:4 (area foto
// kartu h-60 di lebar 420px), resize ke lebar 840px (2x tampil, retina)
// bila sumber lebih lebar — Alfamart (480px) dan BNN (690px) dipakai pada
// lebar aslinya supaya tidak membesar tanpa detail — lalu WebP q80.
// Foto menggantikan area gradasi + huruf awal (PR #95); nama klien, tag
// layanan, dan deskripsi di kartu TIDAK diubah.
//
// Pemetaan nama file -> klien (nama file BNN masih memakai nama lama):
// PLN.jpg -> PLN; Taspen.jpeg -> Taspen; Alfamart.jpg -> Alfamart;
// Medco.jpg -> Medco; Bank_Indonesia.webp -> Bank Indonesia;
// Perempuan_Indonesia_Maju.webp -> Perempuan Indonesia Maju;
// Badan_Narkotika_Nasional.jpg -> BNN.

/** Foto tiap kampanye, dikunci nama klien (sama persis dengan `klien` di KAMPANYE_MARKLO). */
export const FOTO_KAMPANYE: Record<string, string> = {
  'PLN': 'data:image/webp;base64,',
  'Taspen': 'data:image/webp;base64,',
  'Alfamart': 'data:image/webp;base64,',
  'Medco': 'data:image/webp;base64,',
  'Bank Indonesia': 'data:image/webp;base64,',
  'Perempuan Indonesia Maju': 'data:image/webp;base64,',
  'BNN': 'data:image/webp;base64,',
};
